STORY = [('actress', '신입애를 통해서 나한테 전달한 거야?', 'Did you pass the news to me through that rookie kid?', [(923, '신입애를 통해서 나한테 전달한 거야?')], ''), ('joonmo', '드릴 말씀이 없습니다.', 'I have no excuse to offer.', [(924, '드릴 말씀이 없습니다')], ''), ('actress', '내가 물건이니?', 'Am I an object?', [(927, '내가 물건이니?')], ''), ('joonmo', '죄송합니다.', 'I am truly sorry.', [(929, '죄송합니다')], ''), ('actress', '네가 직접 말씀을 드려야지.', 'You should tell a person yourself.', [(935, '네가 직접 말씀을 드려야지')], ''), ('joonmo', '너 도대체 선생님한테 뭐라고 얘기했냐?', 'What on earth did you say to her?', [(944, '너 도대체 선생님한테 뭐라고 얘기했냐?')], ''), ('seungchan', '드라마나 영화 쪽에서 뵙고 싶다고 그랬습니다.', 'I said I hoped to see her in dramas or movies.', [(945, '드라마나 영화 쪽에서 뵙고 싶다고'), (948, '그랬습니다')], ''), ('seungchan', '팀에 변화가 필요하다고 그랬습니다.', 'I said the team needed a change.', [(946, '팀에 변화가 필요하다고'), (948, '그랬습니다')], ''), ('joonmo', '야, 우리가 돌고래냐?', 'Hey, are we dolphins?', [(949, '야 우리가 돌고래냐?')], ''), ('joonmo', '그렇게 말해서 어떻게 알아들어?', 'How can anyone catch on if you talk like that?', [(951, '그렇게 말해서 어떻게 알아들어?')], ''), ('joonmo', '난 널 환영하지 않는다고.', "I'm telling you I don't welcome you.", [(965, '난 널 환영하지 않는다고')], ''), ('joonmo', '그냥 나한테 아무 말도 하지 마.', "Just don't say anything at all to me.", [(967, '그냥 나한테 아무 말을 하지 마')], 'Uses natural 말도 with negative command.')]

WALK = [(0, None, "'Did you pass the news to me through that rookie kid?'"), (1, None, "'I have no excuse to offer.'"), (2, None, "'Am I an object?'"), (3, None, "'I am truly sorry.'"), (4, None, "'You should tell a person yourself.'"), (5, None, "'What on earth did you say to her?'"), (6, None, "'I said I hoped to see her in dramas or movies.'"), (7, None, "'I said the team needed a change.'"), (8, None, "'Hey, are we dolphins?'"), (9, None, "'How can anyone catch on if you talk like that?'"), (10, None, "'I'm telling you I don't welcome you.'"), (11, None, "'Just don't say anything at all to me.'")]
